def transform(grid):
    g = np.array(grid)
    out = g.copy()
    comps = components(g == 3, diagonal=False)
    for comp in comps:
        if len(comp) >= 2:
            for (y, x) in comp:
                out[y, x] = 8
            emit(out, f"Recolour the connected group of {len(comp)} cells of colour 3 "
                      f"(box {bbox(comp)}) to 8; it has more than one cell.")
    emit(out, "Final grid: every multi-cell group of 3 is now 8; isolated single 3s stay 3.")
    return out
